/**
 * Compile a serialized DynamicShapePlan into a native C++ executor.
 * The serialized plan is a binary format produced by DynamicShapePlan.serialize() in Java.
 *
 * @param serializedPlan  Pointer to the serialized plan bytes
 * @param planSize  Size of the serialized plan in bytes
 * @return Opaque handle to the compiled plan, or nullptr on failure
 */
public native @Cast("sd::Pointer") Pointer compileDynamicShapePlan(@Cast("sd::Pointer") Pointer serializedPlan, @ByVal LongType planSize);

/**
 * Execute a compiled native plan.
 *
 * @param planHandle  Handle from compileDynamicShapePlan()
 * @param opContext  OpaqueContext with inputs set via setGraphContextInputArray(), outputs pre-allocated via setGraphContextOutputArray()
 * @param stream  CUDA stream pointer (nullptr for CPU)
 * @return 0 on success, non-zero on failure
 */
public native int executeDynamicShapePlan(
    @Cast("sd::Pointer") Pointer planHandle,
    org.nd4j.nativeblas.OpaqueContext opContext,
    @Cast("sd::Pointer") Pointer stream);

/**
 * Execute through NativeDynamicShapePlan::executeSteadyState, using the same
 * context input order, requested-output mapping and borrowed output ownership
 * as executeDynamicShapePlan. No dtype conversion is performed. The plan owns
 * lifecycle admission (early calls still execute its build phases).
 *
 * @param stream Backend-owned stream: CUDA storage pointer (cudaStream_t*),
 *               VulkanExecutionStream* for Vulkan (nullptr selects the plan's
 *               stream), or the CPU-derived backend's execution stream.
 * @return 0 on success, non-zero on native failure
 */
@Override public native int executeSteadyStatePlan(@Cast("sd::Pointer") Pointer planHandle, org.nd4j.nativeblas.OpaqueContext opContext, @Cast("sd::Pointer") Pointer stream);

/**
 * Free a compiled native plan.
 *
 * @param planHandle  Handle from compileDynamicShapePlan()
 */
public native void freeDynamicShapePlan(@Cast("sd::Pointer") Pointer planHandle);

/**
 * Create a new per-SameDiff native plan cache. Opaque handle owned by caller;
 * free via freeNativePlanCache().
 */
public native @Cast("sd::Pointer") Pointer createNativePlanCache();

/**
 * Destroy a cache created by createNativePlanCache(). Frees all entries.
 */
public native void freeNativePlanCache(@Cast("sd::Pointer") Pointer cacheHandle);

/**
 * Clear all entries from a cache (does NOT delete the cache itself).
 */
public native void clearNativePlanCacheHandle(@Cast("sd::Pointer") Pointer cacheHandle);

/**
 * Get-or-build a NativeDynamicShapePlan keyed by (outputSet, placeholder shape-info, mode).
 *
 * @param cacheHandle           cache from createNativePlanCache (non-null)
 * @param planBytes             serialized Java DynamicShapePlan (for cold-miss build)
 * @param planBytesLen          byte count of planBytes
 * @param outputNames           packed C-string array of output variable names, UTF-8, NUL-separated
 * @param numOutputs            number of output names
 * @param phShapeInfoPtrs       array of shape-info pointers (from ConstantShapeHelper); identity = key equality
 * @param numPlaceholders       length of phShapeInfoPtrs
 * @param graphExecutionMode    GraphExecutionMode ordinal — each mode gets its own plan
 * @param newBorrower           nonzero when this dispatch acquires a new borrower
 *                              lease for the returned shape-keyed plan. Java passes
 *                              this for the first executor dispatch and first use of
 *                              a shape; same-executor same-shape redispatches pass 0
 *                              so lease counts do not grow per token. A nonzero cache
 *                              hit also invalidates external-fed views minted by a
 *                              previous borrower.
 * @return                      NativeDynamicShapePlan* as opaque sd::Pointer; owned by cache
 */
public native @Cast("sd::Pointer") Pointer dispatchNativePlan(@Cast("sd::Pointer") Pointer cacheHandle,
                                             @Cast("sd::Pointer") Pointer planBytes,
                                             @ByVal LongType planBytesLen,
                                             @Cast("sd::Pointer") Pointer outputNames,
                                             @ByVal LongType numOutputs,
                                             @Cast("sd::Pointer") Pointer phShapeInfoPtrs,
                                             @ByVal LongType numPlaceholders,
                                             int graphExecutionMode,
                                             int newBorrower);

/**
 * Unpin a plan handle, making it eligible for LRU eviction.
 * Must be called once for every borrower lease acquired from dispatchNativePlan,
 * when Java swaps away from a plan or closes the executor. The cache keeps the
 * plan eviction-protected until the final lease is released.
 *
 * @param cacheHandle  cache from createNativePlanCache (non-null)
 * @param planHandle   plan handle from dispatchNativePlan (safe to pass null — no-op)
 */
public native void unpinNativePlan(@Cast("sd::Pointer") Pointer cacheHandle, @Cast("sd::Pointer") Pointer planHandle);

/**
 * Clear shape caches in a compiled plan.
 * Must be called when a session resets to avoid stale GPU memory references.
 *
 * @param planHandle  Handle from compileDynamicShapePlan()
 */
public native void clearDynamicShapePlanCaches(@Cast("sd::Pointer") Pointer planHandle);

/**
 * Force-clear ALL shape caches unconditionally (including static slots).
 * Use for session reset or model reload scenarios.
 *
 * @param planHandle  Handle from compileDynamicShapePlan()
 */
public native void clearAllDynamicShapePlanCachesForce(@Cast("sd::Pointer") Pointer planHandle);

/**
 * Release all GPU memory held by intermediate computation results while keeping
 * the plan structure alive. Frees CUDA graph replay handles and associated
 * replay resources,
 * cuBLAS workspace, and non-weight output slot NDArrays. The plan enters a
 * "cold" state and will re-warm on the next execute() call.
 *
 * @param planHandle  Handle from compileDynamicShapePlan()
 * @return the number of intermediate NDArrays freed
 */
public native int releaseGpuIntermediates(@Cast("sd::Pointer") Pointer planHandle);

/** Release producer outputs too. Caller must have completed independent output
 * copies and must retain no borrowed native output pointers. */
public native int releaseGpuIntermediatesAfterOutputCopy(@Cast("sd::Pointer") Pointer planHandle);

